import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] c = new int[n];
        for (int i = 0; i < n; i++) c[i] = sc.nextInt();
        if (n == 1) {
            System.out.println(-1);
            return;
        }
        int lim = c[n - 1] + c[n - 2];
        int INF = 1000000000;
        int[] dp = new int[lim + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int v = 1; v <= lim; v++) {
            for (int x : c) {
                if (x <= v && dp[v - x] + 1 < dp[v]) dp[v] = dp[v - x] + 1;
            }
        }
        int ans = -1;
        for (int v = 1; v < lim; v++) {
            int g = 0, r = v;
            for (int i = n - 1; i >= 0; i--) {
                g += r / c[i];
                r %= c[i];
            }
            if (g > dp[v]) {
                ans = v;
                break;
            }
        }
        System.out.println(ans);
    }
}

