#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<int> c(n);
    for (auto &v : c) cin >> v;
    if (n == 1) {
        cout << -1 << endl;
        return 0;
    }
    int lim = c[n - 1] + c[n - 2];
    const int INF = 1000000000;
    vector<int> dp(lim + 1, INF);
    dp[0] = 0;
    for (int v = 1; v <= lim; v++) {
        for (int x : c) {
            if (x <= v && dp[v - x] + 1 < dp[v]) dp[v] = dp[v - x] + 1;
        }
    }
    int ans = -1;
    for (int v = 1; v < lim; v++) {
        int g = 0, r = v;
        for (int i = n - 1; i >= 0; i--) {
            g += r / c[i];
            r %= c[i];
        }
        if (g > dp[v]) {
            ans = v;
            break;
        }
    }
    cout << ans << endl;
    return 0;
}
